from datetime import date, timedelta
from calendar import monthrange


def recur(start: str, rule: str, count: int) -> list[str]:
    first = date.fromisoformat(start)
    parts = rule.split()
    kind, step = parts[0], int(parts[1])
    weekdays = {
        "MO": 0, "TU": 1, "WE": 2, "TH": 3,
        "FR": 4, "SA": 5, "SU": 6,
    }

    if kind == "DAILY":
        return [
            (first + timedelta(days=i * step)).isoformat()
            for i in range(count)
        ]

    result = []

    if kind == "WEEKLY":
        monday = first - timedelta(days=first.weekday())
        offsets = sorted(weekdays[wd] for wd in parts[2].split(","))

        while True:
            for offset in offsets:
                candidate = monday + timedelta(days=offset)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            monday += timedelta(weeks=step)

    if kind == "MONTHLY":
        month_index = first.year * 12 + first.month - 1

        while True:
            year, zero_based_month = divmod(month_index, 12)
            month = zero_based_month + 1
            first_weekday, last_day = monthrange(year, month)

            if len(parts) == 3:
                requested_day = int(parts[2])
                day = last_day if requested_day == -1 else requested_day
            else:
                occurrence = int(parts[2])
                weekday = weekdays[parts[3]]

                if occurrence == -1:
                    last_weekday = (first_weekday + last_day - 1) % 7
                    day = last_day - (last_weekday - weekday) % 7
                else:
                    day = (
                        1 + (weekday - first_weekday) % 7
                        + 7 * (occurrence - 1)
                    )

            if day <= last_day:
                candidate = date(year, month, day)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result

            month_index += step

    if kind == "YEARLY":
        month, day = map(int, parts[2].split("-"))
        year = first.year

        while True:
            if day <= monthrange(year, month)[1]:
                candidate = date(year, month, day)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            year += step
